            raise InvalidRequest(f"{name} is required")
        return default
    try:
        value = int(raw)
    except (TypeError, ValueError):
        raise InvalidRequest(f"{name} must be an integer") from None
    if minimum is not None and value < minimum:
        raise InvalidRequest(f"{name} must be >= {minimum}")
    if maximum is not None and value > maximum:
        raise InvalidRequest(f"{name} must be <= {maximum}")
    return value


def str_param(params, name, default=None):
    raw = params.get(name)
    if raw is None or str(raw).strip() == "":
        if default is None:
            raise InvalidRequest(f"{name} is required")
        return default
    return str(raw).strip()
"""Paged listing of active orders, newest first."""
from orderfeed.util import page_token


class FeedService:
    def __init__(self, store, settings):
        self.store = store
        self.settings = settings

    def page(self, cursor=None, limit=50):
        head = self.store.head_id()
        if cursor is None:
            offset, top = 0, head
        else:
            token = page_token.decode(cursor)
            page_token.ensure_current(token, head)
            offset, top = token.offset, token.top

        items = self.store.active_page(offset, limit)
        end = offset + len(items)
        if items and end < self.store.count_active():
            next_cursor = page_token.encode(page_token.PageToken(end, top))
        else:
            next_cursor = None
        return {"items": [o.to_dict() for o in items], "next_cursor": next_cursor}
"""Order lifecycle."""
from orderfeed.models import InvalidRequest, NotFound


class OrderService:
    CHANNELS = {"web", "app", "pos"}

    def __init__(self, store, clock):
        self.store = store
        self.clock = clock

    def create(self, customer, amount, channel="web", created_at=None):
        if channel not in self.CHANNELS:
            raise InvalidRequest(f"unknown channel {channel!r}")
        if created_at is None:
            created_at = self.clock.now()
        elif created_at > self.clock.now():
            raise InvalidRequest("created_at is in the future")
        return self.store.insert(customer, amount, created_at, channel)

    def get(self, order_id):
        order = self.store.get(order_id)
        if order is None:
            raise NotFound(f"order {order_id}")
        return order

    def cancel(self, order_id):
        if self.store.get(order_id) is None:
            raise NotFound(f"order {order_id}")
        if not self.store.cancel(order_id):
            raise InvalidRequest(f"order {order_id} is already cancelled")
"""Daily sales report."""
from collections import OrderedDict

from orderfeed.util.money import format_amount

DAY = 86_400


class ReportService:
    def __init__(self, store, settings):
        self.store = store
        self.settings = settings

    def _local_day(self, ts):
        return (ts + self.settings.report_timezone_offset_hours * 3600) // DAY

    def daily(self, start=0, end=2**40):
        totals = OrderedDict()
        for order in reversed(self.store.active_between(start, end)):
            day = self._local_day(order.created_at)
            count, amount = totals.get(day, (0, 0))
            totals[day] = (count + 1, amount + order.amount)
        rows = []
        for day, (count, amount) in totals.items():
            rows.append({
                "day": day,
                "orders": count,
                "amount": amount,
                "display": format_amount(amount, self.settings.currency),
            })
        return {"days": rows}
"""sqlite-backed order storage."""
import sqlite3

from orderfeed.models import Order

SCHEMA = """
CREATE TABLE orders (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    customer   TEXT    NOT NULL,
    amount     INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    channel    TEXT    NOT NULL DEFAULT 'web',
    cancelled  INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX orders_feed ON orders (cancelled, created_at DESC, id DESC);
"""

_COLUMNS = "id, customer, amount, created_at, channel, cancelled"
_FEED_ORDER = "ORDER BY created_at DESC, id DESC"


def _row_to_order(row):
    return Order(row[0], row[1], row[2], row[3], row[4], bool(row[5]))


class OrderStore:
    def __init__(self, path=":memory:"):
        self._conn = sqlite3.connect(path)
        self._conn.executescript(SCHEMA)

    def insert(self, customer, amount, created_at, channel="web"):
        cur = self._conn.execute(
            "INSERT INTO orders (customer, amount, created_at, channel) VALUES (?, ?, ?, ?)",
            (customer, amount, created_at, channel),
        )
        self._conn.commit()
        return self.get(cur.lastrowid)

    def get(self, order_id):
        row = self._conn.execute(f"SELECT {_COLUMNS} FROM orders WHERE id = ?", (order_id,)).fetchone()
        return _row_to_order(row) if row else None

    def cancel(self, order_id):
        cur = self._conn.execute(
            "UPDATE orders SET cancelled = 1 WHERE id = ? AND cancelled = 0", (order_id,)
        )
        self._conn.commit()
        return cur.rowcount == 1

    def count_active(self):
        return self._conn.execute("SELECT COUNT(*) FROM orders WHERE cancelled = 0").fetchone()[0]

    def head_id(self):
        row = self._conn.execute(
            f"SELECT id FROM orders WHERE cancelled = 0 {_FEED_ORDER} LIMIT 1"
        ).fetchone()
        return row[0] if row else None

    def active_page(self, offset, limit):
        rows = self._conn.execute(
            f"SELECT {_COLUMNS} FROM orders WHERE cancelled = 0 {_FEED_ORDER} LIMIT ? OFFSET ?",
            (limit, offset),
        ).fetchall()
        return [_row_to_order(r) for r in rows]

    def active_between(self, start, end):
        rows = self._conn.execute(
            f"SELECT {_COLUMNS} FROM orders WHERE cancelled = 0 AND created_at >= ? AND created_at < ?"
            " ORDER BY created_at DESC",
            (start, end),
        ).fetchall()
        return [_row_to_order(r) for r in rows]
